    labels: (s, c) => (s.y ? [{ id: "t", p: [-0.2, s.y + 0.22, 0], t: "Soil + water + indicator" }, { id: "ch", p: [0.32, s.y + 0.02, 0.05], t: "Colour chart pH 4 → 9" }, { id: "m", p: [0.35, s.y + 0.05, -0.2], t: "pH meter reads " + PH[+c.i][1] }] : []),
    hud: (s, c) => { const p = PH[+c.i][1]; return [{ title: PH[+c.i][0] + " — pH " + p, lines: [[p < 5.5 ? "Strongly acid: lime the soil; nutrients (P) locked; Al toxicity" : p < 6.5 ? "Slightly acid: good for most crops" : p <= 7.3 ? "Neutral: ideal" : "Alkaline: add organic matter or sulphur; micronutrients locked", "#ffd27a", true], "pH below 7 = acid, 7 = neutral, above 7 = alkaline.", "Most crops grow best between pH 6 and 7."] }]; },
