    steps: (s, c) => { const R = MK.scenes["PC-3"].calc(c); return ["Area per stand = " + c.row / 100 + " m × " + c.inrow / 100 + " m = " + f(c.row * c.inrow / 1e4, 4) + " m²", "Stands per ha = 10,000 ÷ " + f(c.row * c.inrow / 1e4, 4) + " = " + Math.round(10000 / (c.row * c.inrow / 1e4)), "Plants = stands × " + c.spp + " = " + Math.round(R.pop), "Seed rate = " + Math.round(R.pop) + " × " + c.tsw + " g ÷ 1000 ÷ 1000 × 100 ÷ " + c.germ + " = " + f(R.rate, 4) + " kg/ha"]; },
