      if (c.m === "cut") { pot(-0.2); g.add(AK.cyl(0.012, 0.012, 0.3, bark, -0.2, y + 0.24, 0, 8)); for (let i = 0; i < 5; i++) { const rt = AK.cyl(0.002, 0.002, 0.06, AK.std(0xf0e8d0), -0.2 + (i - 2) * 0.01, y + 0.08, 0, 4); rt.rotation.z = (i - 2) * 0.4; g.add(rt); } const cs = AK.plant("cassava", 0.3, { seed: 1 }); cs.scale.setScalar(0.25); cs.position.set(0.25, y + 0.12, 0); pot(0.25); g.add(cs); }
      else if (c.m === "lay") { const tr = AK.plant("citrus", 0.6, { seed: 2 }); tr.scale.setScalar(0.18); tr.position.set(0, y, 0); g.add(tr); const ball = AK.sph(0.04, AK.std(0x7a6a4a, { roughness: 1 }), 0.12, y + 0.42, 0.05); ball.scale.set(1, 1.4, 1); g.add(ball); g.add(AK.cyl(0.042, 0.042, 0.005, AK.std(0x2a2a2a), 0.12, y + 0.47, 0.05, 12), AK.cyl(0.042, 0.042, 0.005, AK.std(0x2a2a2a), 0.12, y + 0.37, 0.05, 12)); }
      else if (c.m === "bud" || c.m === "graft") { pot(-0.15); const stock = AK.cyl(0.015, 0.018, 0.35, bark, -0.15, y + 0.29, 0, 10); g.add(stock); if (c.m === "bud") { g.add(AK.box(0.004, 0.04, 0.02, AK.std(0x8aa04a), -0.135, y + 0.3, 0)); g.add(AK.box(0.034, 0.008, 0.034, AK.phys(0xe8e8f0, { transparent: true, opacity: 0.7 }), -0.15, y + 0.3, 0)); const bud = AK.sph(0.006, green, -0.132, y + 0.3, 0); g.add(bud); } else { const sc = AK.cyl(0.013, 0.015, 0.15, AK.std(0x6a7a3a), -0.15, y + 0.54, 0, 10); g.add(sc); g.add(AK.cyl(0.02, 0.02, 0.05, AK.phys(0xe8e8f0, { transparent: true, opacity: 0.6 }), -0.15, y + 0.47, 0, 12)); for (let i = 0; i < 3; i++) { const lf = new T3.Mesh(AK.leafGeo(0.08, 0.03, 0.2, 2), AK.leafMat ? AK.leafMat() : green); lf.position.set(-0.15, y + 0.6, 0); lf.rotation.set(0.6, i * 2.1, 0); g.add(lf); } } const k2 = AK.tool(c.m === "bud" ? "buddingknife" : "pruningknife"); k2.scale.setScalar(0.25); k2.position.set(0.25, y, 0.1); g.add(k2); }
      else if (c.m === "suck") { const b = AK.plant("banana", 0.8, { seed: 3 }); b.scale.setScalar(0.15); b.position.set(-0.1, y, 0); g.add(b); const sk = AK.plant("banana", 0.2, { seed: 4 }); sk.scale.setScalar(0.12); sk.position.set(0.25, y, 0.05); g.add(sk); }
