  const PRES = { smoke: ["Smoking", "Fish are hung over a smoky fire in a kiln (e.g. Chorkor smoker); dries and flavours; keeps weeks."], sun: ["Sun drying", "Fish split and dried on raised racks in the sun; cheap but slow and dirty."], salt: ["Salting", "Salt draws out water and stops bacteria; often combined with drying."], freeze: ["Freezing / icing", "Fish kept on ice or in freezers; keeps freshness."], can: ["Canning", "Fish cooked and sealed in airtight tins; industrial."] };
  AK.tour("PD-8", Object.assign({}, { sky: "waterkloof_farm" }, { title: "Fish harvesting and preservation", blurb: "Fish are harvested by draining the pond or seining, then processed and preserved to prevent spoilage.", cam: [[0, 2.2, 4.6], [0, 0.6, 0]],
    variants: Object.entries(PRES).map(([k, v]) => [k, v[0]]), vlabel: "Method",
    build(g, S, s, c) { const h = AK.ground(g, { w: 8, d: 5, amp: 0.01 }); const v = c.v; if (v === "smoke") { g.add(AK.box(1.2, 0.8, 0.8, AK.pbr("clay_block_wall"), 0, 0.4, 0)); for (let i = 0; i < 8; i++) AK.put(g, AK.fish("catfish", 0.2), -0.4 + (i % 4) * 0.27, (i < 4 ? -0.15 : 0.15), () => 0.84, 0); s.sm = GK.particles(60, 0xcfcfcf, 0.12, 0.35); g.add(s.sm); } else { s.sm = null; } if (v === "sun") { g.add(AK.box(2, 0.03, 0.8, AK.pbr("Wicker004", { repeat: 2 }), 0, 0.7, 0)); [[-0.9, -0.35], [0.9, -0.35], [-0.9, 0.35], [0.9, 0.35]].forEach(([x, z]) => g.add(AK.cyl(0.03, 0.03, 0.7, AK.wood(), x, 0.35, z, 6))); for (let i = 0; i < 10; i++) AK.put(g, AK.fish("tilapia", 0.18), -0.8 + (i % 5) * 0.4, (i < 5 ? -0.2 : 0.2), () => 0.74, 0); } if (v === "salt") { g.add(AK.cyl(0.4, 0.35, 0.4, AK.phys(0x2a5aa8), 0, 0.2, 0, 24)); g.add(AK.cyl(0.38, 0.38, 0.02, AK.phys(0xf4f4f4, { roughness: 0.9 }), 0, 0.39, 0, 24)); for (let i = 0; i < 5; i++) AK.put(g, AK.fish("tilapia", 0.16), -0.2 + (i % 3) * 0.2, -0.1 + Math.floor(i / 3) * 0.2, () => 0.41, i); } if (v === "freeze") { g.add(AK.box(1.2, 0.8, 0.7, AK.paint(0xf4f4f8), 0, 0.4, 0)); g.add(AK.box(1.1, 0.02, 0.6, AK.phys(0xcfe6ff, { transparent: true, opacity: 0.6 }), 0, 0.81, 0)); for (let i = 0; i < 6; i++) AK.put(g, AK.fish("tilapia", 0.16), -0.4 + (i % 3) * 0.4, -0.15 + Math.floor(i / 3) * 0.3, () => 0.84, 0); } if (v === "can") for (let i = 0; i < 12; i++) g.add(AK.cyl(0.05, 0.05, 0.1, AK.metal(0xd8d8dc), -0.5 + (i % 6) * 0.2, 0.05 + Math.floor(i / 6) * 0.1, 0, 18)); },
    tick(S, s, c, dt) { s.t = (s.t || 0) + dt; if (s.sm) { for (let i = 0; i < 60; i++) { const u = (i / 60 + s.t * 0.15) % 1; s.sm.pos[i * 3] = Math.sin(i + s.t) * 0.3 * u; s.sm.pos[i * 3 + 1] = 0.9 + u * 1.6; s.sm.pos[i * 3 + 2] = Math.cos(i) * 0.2 * u; } s.sm.flush(); } },
    feats: (c) => [{ id: "m", n: PRES[c.v][0], p: [0, 1.2, 0], d: PRES[c.v][1] }],
    notes: ["Harvesting: partial (seine net, cast net) or total (drain the pond). Harvest in the cool of the morning.", "Fish spoil fast because of enzymes, bacteria and high moisture."], tasks: ["Describe four methods of preserving fish.", "Why does fish spoil quickly?"] }));
